<?php declare(strict_types=1);
$flag=static function(string $locale):string{return '<span class="language-flag" aria-hidden="true"><svg viewBox="0 0 32 32">'.($locale==='vi'?'<path fill="#da251d" d="M0 0h32v32H0z"/><path fill="#ffdf00" d="m16 6 2.4 7.2H26l-6.1 4.5 2.3 7.3-6.2-4.5L9.8 25l2.3-7.3L6 13.2h7.6z"/>':'<path fill="#012169" d="M0 0h32v32H0z"/><path stroke="#fff" stroke-width="7" d="m0 0 32 32M32 0 0 32"/><path stroke="#c8102e" stroke-width="3" d="m0 0 32 32M32 0 0 32"/><path stroke="#fff" stroke-width="11" d="M16 0v32M0 16h32"/><path stroke="#c8102e" stroke-width="6" d="M16 0v32M0 16h32"/>').'</svg></span>';};
?>
<details class="language-picker"><summary class="language-trigger" aria-label="<?=$en?'Language: English':'Ngôn ngữ: Tiếng Việt'?>"><?=$flag($lang)?><span><?=$en?'EN':'VI'?></span><svg class="language-chevron" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></summary><ul class="language-options" aria-label="<?=$en?'Choose language':'Chọn ngôn ngữ'?>"><?php foreach(['vi','en'] as $locale):?><li><?php if(isset($languagePaths[$locale])):?><a href="<?=$e($languagePaths[$locale])?>" hreflang="<?=$locale?>" lang="<?=$locale?>"<?=$lang===$locale?' aria-current="page"':''?>><?=$flag($locale)?><span><?=$locale==='vi'?'Tiếng Việt':'English'?></span><?php if($lang===$locale):?><span class="language-selected" aria-hidden="true">✓</span><?php endif;?></a><?php else:?><span class="language-unavailable" aria-disabled="true"><?=$flag($locale)?><span><?=$locale==='vi'?'Tiếng Việt':'English'?><small><?=$en?'Not available':'Chưa có bản dịch'?></small></span></span><?php endif;?></li><?php endforeach;?></ul></details>
